with with_window as (select src.*, sub.id as subscription_id, sub.plan, sub.monthly_fee from accounts src left join subscriptions sub on src.customer_id = sub.customer_id and src.opened_date >= sub.start_date and src.opened_date <= date_add(sub.end_date, 10)) select id, account_type, balance, opened_date, status, subscription_id, plan, monthly_fee from with_window order by opened_date, subscription_id;
